export const PLUGIN_FILES: Record<string, string> = {
  "plugin/bash/adapter.bash": "# bash adapter: hooks, readline access, history.\n#\n# bash has no pre-execution hook, so this adapter deliberately does *not*\n# intercept Enter:\n#   * natural language is simply executed and lands in the\n#     command-not-found path (the shell prints one \"command not found\" line);\n#   * bind -x on Enter would consume that keystroke, and bash cannot pass it\n#     through in the same keypress without eval (which breaks interactive\n#     programs) — measured.\n# Delivery of a suggestion therefore uses a one-shot Enter handler, armed only\n# while a suggestion is pending: the Enter that would have been a no-op on an\n# empty line accepts the suggestion instead.\n\n_ai_shell_adapter_init() {\n  command_not_found_handle() { AI_SHELL_LAST_CMD=\"$*\"; _ai_shell_on_not_found \"$1\"; }\n\n  # Ours must run first: every other PROMPT_COMMAND entry would clobber $?.\n  local entry=_ai_shell_bash_prompt\n  if [[ $(declare -p PROMPT_COMMAND 2>/dev/null) == \"declare -a\"* ]]; then\n    local -a rebuilt=(\"$entry\")\n    local existing\n    for existing in \"${PROMPT_COMMAND[@]}\"; do\n      [[ $existing == \"$entry\" ]] || rebuilt+=(\"$existing\")\n    done\n    PROMPT_COMMAND=(\"${rebuilt[@]}\")\n  else\n    case \";${PROMPT_COMMAND-};\" in\n      *\";$entry;\"*) : ;;\n      *) PROMPT_COMMAND=\"$entry${PROMPT_COMMAND:+;$PROMPT_COMMAND}\" ;;\n    esac\n  fi\n\n  trap _ai_shell_bash_exit EXIT\n}\n\n_ai_shell_adapter_finish() { return 0; }\n\n# bash's `history` prints \"  <n>  <command>\"; strip the number (and any\n# HISTTIMEFORMAT prefix) without forking.\n_ai_shell_bash_strip_number() {\n  local text=$1\n  text=${text#\"${text%%[![:space:]]*}\"}      # leading blanks\n  [[ $text == \\[*\\]* ]] && text=${text#*]}   # HISTTIMEFORMAT prefix, if any\n  text=${text#\"${text%%[![:space:]]*}\"}\n  text=${text#\"${text%%[!0-9]*}\"}            # the entry number\n  text=${text#\"${text%%[![:space:]]*}\"}      # blanks after it\n  printf '%s' \"$text\"\n}\n\n_ai_shell_adapter_history() {\n  local limit=${1:-20} line\n  local -a lines=()\n  while IFS= read -r line; do\n    line=$(_ai_shell_bash_strip_number \"$line\")\n    [[ -n $line ]] && lines+=(\"$line\")\n  done < <(history \"$limit\" 2>/dev/null)\n  (( ${#lines[@]} )) && printf '%s\\n' \"${lines[@]}\"\n  return 0\n}\n\n_ai_shell_bash_last_command() {\n  local line\n  line=$(history 1 2>/dev/null) || return 0\n  _ai_shell_bash_strip_number \"$line\"\n}\n\n_ai_shell_adapter_not_found_message() { printf 'bash: %s: command not found\\n' \"$1\" >&2; }\n\n_ai_shell_adapter_command_exists() { command -v -- \"$1\" >/dev/null 2>&1; }\n\n# bash enables this by default, so suggestions can carry their rationale inline.\n_ai_shell_adapter_supports_comment() { shopt -q interactive_comments; }\n\n_ai_shell_adapter_notice() {\n  [[ -t 1 ]] || return 0\n  printf '\\033[2m%s\\033[0m\\n' \"$1\"\n}\n\n# Arm the one-shot Enter handler.  `bind` only affects the current shell, so this\n# must run in the prompt hook (never inside the command-not-found subshell).\n_ai_shell_adapter_pending_ready() {\n  [[ $- == *i* ]] || return 0\n  bind -x '\"\\C-m\": _ai_shell_bash_accept' 2>/dev/null || return 0\n  _ai_shell_adapter_notice '（bash 无法自动预填：按 Enter 填入建议，再按 Enter 执行）'\n}\n\n_ai_shell_bash_accept() {\n  # The user started typing instead of accepting — never clobber their line.\n  if [[ -n ${READLINE_LINE-} ]]; then\n    bind '\"\\C-m\": accept-line'\n    return 0\n  fi\n  local suggestion\n  suggestion=$(cat \"$AI_SHELL_PENDING\" 2>/dev/null)\n  READLINE_LINE=$suggestion\n  READLINE_POINT=${#suggestion}\n  rm -f -- \"$AI_SHELL_PENDING\"\n  bind '\"\\C-m\": accept-line'\n}\n\n_ai_shell_bash_prompt() {\n  local ret=$? marker=${HISTCMD:-0}\n  # An empty line keeps $? (measured), so without this guard a bare Enter after a\n  # failure would re-analyse the same command on every keystroke-less prompt.\n  if [[ $marker == \"${AI_SHELL_LAST_HISTCMD:-}\" ]]; then\n    _ai_shell_on_prompt 0 \"\"\n    return $ret\n  fi\n  AI_SHELL_LAST_HISTCMD=$marker\n  _ai_shell_on_prompt \"$ret\" \"$(_ai_shell_bash_last_command)\"\n  return $ret\n}\n\n_ai_shell_adapter_doctor() {\n  if declare -F command_not_found_handle >/dev/null 2>&1; then\n    printf 'not-found   : ai-shell 已接管\\n'\n  else\n    printf 'not-found   : 未接管\\n'\n  fi\n  case \"${PROMPT_COMMAND-}\" in\n    *_ai_shell_bash_prompt*) printf 'prompt hook : 已挂载\\n' ;;\n    *) printf 'prompt hook : 未挂载\\n' ;;\n  esac\n  printf 'comments    : %s\\n' \"$(shopt -q interactive_comments && printf on || printf off)\"\n}\n\n_ai_shell_bash_exit() {\n  # Subshells inherit the EXIT trap; only the main shell may clean up.\n  [[ ${BASHPID:-$$} == $$ ]] || return 0\n  rm -rf -- \"$AI_SHELL_SESSION_DIR\"\n}\n",
  "plugin/bash/ai-shell.bash": "# AI Shell — bash integration entry point (bash 5+; macOS needs `brew install bash`).\n#\n# The policy, context assembly and runtime bridge live in\n# plugin/lib/ai-shell-core.sh; this directory only implements what is\n# bash-specific (see plugin/bash/adapter.bash).\n\n[[ -n ${AI_SHELL_LOADED-} ]] && return 0\nAI_SHELL_LOADED=1\nAI_SHELL_NAME=bash\nAI_SHELL_EXT=bash\n\n# <repo>/plugin/bash/ai-shell.bash -> <repo>\nAI_SHELL_ROOT=$(cd -- \"$(dirname -- \"${BASH_SOURCE[0]}\")/../..\" && pwd)\n\n. \"$AI_SHELL_ROOT/plugin/lib/ai-shell-core.sh\"\n. \"$AI_SHELL_ROOT/plugin/bash/adapter.bash\"\n\n_ai_shell_setup\n",
  "plugin/lib/ai-shell-core.sh": "# ai-shell core — shell-agnostic policy, context assembly and the runtime bridge.\n#\n# Sourced by plugin/<shell>/ai-shell.*.  Nothing in here may use shell-specific\n# syntax: it runs under both zsh and bash.  Everything that *is*\n# shell-specific — hooks, line-editor access, history, option names — lives in\n# the per-shell adapter, which must provide:\n#\n#   _ai_shell_adapter_init                  register the shell's hooks\n#   _ai_shell_adapter_finish                unregister the shell's hooks\n#   _ai_shell_adapter_history <n>           print up to n recent commands\n#   _ai_shell_adapter_command_exists <word> 0 = the shell can resolve it\n#   _ai_shell_adapter_supports_comment      0 = '#' starts a comment here\n#   _ai_shell_adapter_pending_ready <cmd>   the shell may deliver a suggestion\n#   _ai_shell_adapter_notice <text>         one dim hint line (may be a no-op)\n#   _ai_shell_adapter_doctor                print shell-side facts\n#\n# Contract with the runtime (unchanged across shells): 11 NUL-separated fields\n# on stdin, human-readable panel on stdout, suggestion via --command-out.\n\n_ai_shell_setup() {\n  : \"${AI_SHELL_ROOT:?ai-shell core needs AI_SHELL_ROOT}\"\n  : \"${AI_SHELL_NAME:?ai-shell core needs AI_SHELL_NAME}\"\n\n  # `$$` is the *main* shell's pid in both shells, so subshells (the\n  # command-not-found handler runs in one) share the parent's session.\n  AI_SHELL_SESSION_DIR=\"${TMPDIR:-/tmp}/ai-shell-${UID:-$(id -u)}-$$\"\n  export AI_SHELL_SESSION_DIR\n  [[ -d $AI_SHELL_SESSION_DIR ]] || mkdir -p -- \"$AI_SHELL_SESSION_DIR\"\n  AI_SHELL_PENDING=$AI_SHELL_SESSION_DIR/pending\n  AI_SHELL_CNF_FLAG=$AI_SHELL_SESSION_DIR/cnf-handled\n\n  AI_SHELL_LOG_FILE=${AI_SHELL_LOG_FILE:-$AI_SHELL_SESSION_DIR/log}\n  AI_SHELL_MAX_EXIT_AI=${AI_SHELL_MAX_EXIT_AI:-3}\n  AI_SHELL_FAIL_STREAK=${AI_SHELL_FAIL_STREAK:-0}\n  AI_SHELL_LAST_CMD=\"\"\n  AI_SHELL_QUERY=\"\"\n  # Commands whose non-zero exit is normal, not a failure to explain.\n  AI_SHELL_IGNORE=${AI_SHELL_IGNORE:-\"grep egrep fgrep rg ag ack diff cmp test [ [[ false\"}\n\n  _ai_shell_resolve_runtime\n  _ai_shell_adapter_init\n}\n\n# How the runtime is invoked: an explicit binary (AI_SHELL_BIN), one installed on\n# PATH, or — for in-repo development — node running the TypeScript directly.\n_ai_shell_resolve_runtime() {\n  if [[ -n ${AI_SHELL_BIN:-} ]]; then\n    AI_SHELL_CMD=(\"$AI_SHELL_BIN\")\n  elif command -v ai-shell >/dev/null 2>&1; then\n    AI_SHELL_CMD=(\"$(command -v ai-shell)\")\n  else\n    AI_SHELL_CMD=(node \"$AI_SHELL_ROOT/runtime/main.ts\")\n  fi\n}\n\n_ai_shell_reload() {\n  unset AI_SHELL_LOADED\n  _ai_shell_adapter_finish\n  . \"$AI_SHELL_ROOT/plugin/$AI_SHELL_NAME/ai-shell.$AI_SHELL_EXT\"\n}\n\n# --- small utilities used by every shell ------------------------------------\n\n_ai_shell_first_word() {\n  local s=$1\n  s=${s#\"${s%%[![:space:]]*}\"}\n  printf '%s' \"${s%%[[:space:]]*}\"\n}\n\n# $1 = command name; uses the shell's own resolution via the adapter.\n_ai_shell_ignored() {\n  case \" $AI_SHELL_IGNORE $AI_SHELL_IGNORE_EXTRA \" in\n    *\" $1 \"*) return 0 ;;\n  esac\n  return 1\n}\n\n# Monotonic-ish milliseconds; EPOCHREALTIME exists in zsh (zsh/datetime) and\n# bash >= 5.  `10#` keeps the fractional digits from being read as octal.\n_ai_shell_now_ms() {\n  local t=${EPOCHREALTIME:-} frac\n  if [[ -n $t ]]; then\n    # Fraction precision differs per shell (bash: µs, zsh: ns) — take 3 digits.\n    frac=\"${t#*.}000\"\n    printf '%s' \"$(( ${t%.*} * 1000 + 10#${frac:0:3} ))\"\n  else\n    printf '%s' \"$(( ${EPOCHSECONDS:-0} * 1000 ))\"\n  fi\n}\n\n_ai_shell_log() {\n  # $1 trigger $2 ms $3 rc $4 command\n  [[ -n ${AI_SHELL_LOG:-} ]] || return 0\n  printf '%s\\n' \"trigger=$1 ms=$2 rc=$3 cmd=$4\" >> \"$AI_SHELL_LOG_FILE\"\n}\n\n# --- context + runtime -------------------------------------------------------\n\n# Field order is fixed by runtime/context.ts.  The trailing \"  # rationale\" the\n# runtime appends to suggestions is stripped: fed back as context it made the\n# model explain its own comment instead of the failure.\n_ai_shell_context() {\n  # $1=trigger $2=buffer $3=last command $4=exit code\n  printf '%s\\0' \"1\"\n  printf '%s\\0' \"$AI_SHELL_NAME\"\n  printf '%s\\0' \"$PWD\"\n  printf '%s\\0' \"${2%%  \\# *}\"\n  printf '%s\\0' \"${3%%  \\# *}\"\n  printf '%s\\0' \"$4\"\n  printf '%s\\0' \"$1\"\n  printf '%s\\0' \"$(_ai_shell_adapter_history 20)\"\n  printf '%s\\0' \"$(env)\"\n  printf '%s\\0' \"$AI_SHELL_PENDING\"\n  printf '%s\\0' \"$(uname -srm 2>/dev/null)\"\n}\n\n# Runs the runtime: it streams the panel to the terminal and writes the\n# suggestion to the pending file.  Always returns 0 — a broken AI call must\n# never change the shell's behaviour.\n_ai_shell_ask() {\n  # $1=trigger $2=buffer $3=last command $4=exit code\n  local trigger=$1 start_ms\n  start_ms=$(_ai_shell_now_ms)\n  rm -f -- \"$AI_SHELL_PENDING\"\n\n  local -a extra=()\n  [[ -n ${AI_SHELL_MODEL:-} ]] && extra+=(--model \"$AI_SHELL_MODEL\")\n  [[ -n ${AI_SHELL_TIMEOUT_MS:-} ]] && extra+=(--timeout \"$AI_SHELL_TIMEOUT_MS\")\n  if _ai_shell_adapter_supports_comment; then extra+=(--comment); fi\n\n  _ai_shell_context \"$@\" | \"${AI_SHELL_CMD[@]}\" ask --command-out \"$AI_SHELL_PENDING\" \"${extra[@]}\"\n  local rc=$?\n\n  _ai_shell_log \"$trigger\" \"$(( $(_ai_shell_now_ms) - start_ms ))\" \"$rc\" \"$3\"\n  return 0\n}\n\n# --- trigger policies --------------------------------------------------------\n\n# Non-ASCII and nothing the shell can resolve ⇒ the user typed a question, not a\n# command.  Shared by the pre-execution hook (zsh) and the command-not-found\n# handler (bash) so both shells frame the input the same way.\n_ai_shell_looks_like_natural_language() {\n  local line=$1 first saved_lc=${LC_ALL-}\n  case ${line:0:1} in\n    '' | '#' | '|' | '&' | ';' | '(' | ')' | '<' | '>') return 1 ;;\n  esac\n  # LC_ALL=C makes [:print:] byte-based, so non-ASCII is detected regardless of\n  # the user's locale.\n  LC_ALL=C\n  case $line in\n    *[![:print:][:space:]]*) : ;;\n    *) LC_ALL=$saved_lc; return 1 ;;\n  esac\n  LC_ALL=$saved_lc\n  first=$(_ai_shell_first_word \"$line\")\n  [[ -n $first ]] || return 1\n  case $first in\n    */*) return 1 ;;   # a path: let the shell report it, it is not a question\n  esac\n  _ai_shell_adapter_command_exists \"$first\" && return 1\n  return 0\n}\n\n# Natural language typed at the prompt (shells with a pre-execution hook).\n# Deliberately conservative: everything that is not clearly a question goes to\n# the shell untouched.\n_ai_shell_should_intercept_line() {\n  [[ -n ${AI_SHELL_DISABLE:-} ]] && return 1\n  _ai_shell_looks_like_natural_language \"$1\"\n}\n\n# Called by the shell's command-not-found hook (runs in a subshell in both zsh\n# and bash, so only file-based side effects survive).\n_ai_shell_on_not_found() {\n  local cmd=$1 line=${AI_SHELL_LAST_CMD:-$1}\n\n  if [[ -n ${AI_SHELL_DISABLE:-} ]]; then\n    _ai_shell_adapter_not_found_message \"$cmd\"\n    return 127\n  fi\n\n  if _ai_shell_looks_like_natural_language \"$line\"; then\n    # A question, not a mistyped command: skip the shell's own error line and\n    # send it as natural language, so the model answers it instead of explaining\n    # why bash said \"command not found\".\n    : > \"$AI_SHELL_CNF_FLAG\"\n    _ai_shell_ask nl \"$line\" \"\" 127\n    return 127\n  fi\n\n  _ai_shell_adapter_not_found_message \"$cmd\"\n  : > \"$AI_SHELL_CNF_FLAG\"\n  _ai_shell_ask command_not_found \"$line\" \"$cmd\" 127\n  return 127\n}\n\n# Called once per prompt, with the exit status of the command that just ran.\n_ai_shell_on_prompt() {\n  local ret=$1 last=${2:-} handled=0\n\n  if [[ -n ${AI_SHELL_QUERY:-} ]]; then\n    # A natural-language line intercepted before execution (see the adapter).\n    local query=$AI_SHELL_QUERY\n    AI_SHELL_QUERY=\"\"\n    _ai_shell_ask nl \"$query\" \"\" \"\"\n    _ai_shell_queue_pending\n    return $ret\n  fi\n\n  if [[ -e $AI_SHELL_CNF_FLAG ]]; then\n    rm -f -- \"$AI_SHELL_CNF_FLAG\"\n    handled=1\n  fi\n\n  if (( handled == 0 )) && [[ -z ${AI_SHELL_DISABLE:-} ]]; then\n    if (( ret == 0 || ret == 130 )); then\n      AI_SHELL_FAIL_STREAK=0\n    else\n      local first\n      first=$(_ai_shell_first_word \"$last\")\n      if [[ -n $first ]] && ! _ai_shell_ignored \"$first\"; then\n        AI_SHELL_FAIL_STREAK=$(( AI_SHELL_FAIL_STREAK + 1 ))\n        if (( AI_SHELL_FAIL_STREAK <= AI_SHELL_MAX_EXIT_AI )); then\n          _ai_shell_ask non_zero_exit \"$last\" \"$last\" \"$ret\"\n        fi\n      fi\n    fi\n  fi\n\n  _ai_shell_queue_pending\n  return $ret\n}\n\n# Hands a pending suggestion to the shell's delivery mechanism.  zsh pre-fills\n# the next buffer by itself (zle-line-init); bash needs an explicit hand-off.\n_ai_shell_queue_pending() {\n  [[ -s $AI_SHELL_PENDING ]] || return 0\n  _ai_shell_adapter_pending_ready \"$(cat \"$AI_SHELL_PENDING\")\"\n}\n\n# Shell-side facts for `ai-shell doctor`.\n_ai_shell_doctor() {\n  printf 'shell       : %s\\n' \"$AI_SHELL_NAME\"\n  _ai_shell_adapter_doctor\n  printf 'runtime     : %s\\n' \"${AI_SHELL_CMD[*]}\"\n  printf 'session dir : %s %s\\n' \"$AI_SHELL_SESSION_DIR\" \"$([[ -w $AI_SHELL_SESSION_DIR ]] && printf '可写' || printf '不可写')\"\n}\n\n# User-facing entry points (both shells get the same names).\nai-shell-doctor() { _ai_shell_doctor; }\nai-shell-reload() { _ai_shell_reload; }\n",
  "plugin/zsh/adapter.zsh": "# zsh adapter: hooks, line-editor access, history.\n#\n# Everything here is zsh-specific.  The core calls these; see\n# plugin/lib/ai-shell-core.sh for the interface.\n\n_ai_shell_adapter_init() {\n  autoload -Uz add-zsh-hook add-zle-hook-widget\n  add-zsh-hook preexec _ai_shell_zsh_preexec\n  add-zsh-hook precmd _ai_shell_zsh_precmd\n  add-zsh-hook zshexit _ai_shell_zsh_exit\n\n  # Scenario 2.  zsh runs this in a subshell (measured), so the suggestion can\n  # only travel to the parent through the pending file.\n  command_not_found_handler() { _ai_shell_on_not_found \"$1\"; }\n\n  # Compose: keep whatever already owned accept-line (another plugin's wrapper).\n  if [[ -v widgets[accept-line] && ${widgets[accept-line]} != builtin ]]; then\n    zle -A accept-line _ai_shell_outer_accept\n  fi\n  zle -N accept-line _ai_shell_zsh_accept_line\n  add-zle-hook-widget line-init _ai_shell_zsh_line_init\n}\n\n_ai_shell_adapter_finish() {\n  # add-zsh-hook / add-zle-hook-widget ignore duplicates, so a reload is safe.\n  return 0\n}\n\n_ai_shell_adapter_history() {\n  local limit=${1:-20}\n  local -a keys=(${(on)${(k)history}}) recent=()\n  # A short array would make ${arr[-limit,-1]} empty in zsh — clamp explicitly.\n  (( ${#keys} > limit )) && keys=(\"${keys[-${limit},-1]}\")\n  local key\n  for key in \"${keys[@]}\"; do recent+=(\"${history[$key]}\"); done\n\n  # A fresh shell's $history is empty (zsh does not preload the history file).\n  if (( ${#recent} < limit )) && [[ -r ${HISTFILE-} ]]; then\n    local line\n    local -a past=()\n    for line in \"${(@f)$(command tail -n \"$limit\" -- \"$HISTFILE\" 2>/dev/null)}\"; do\n      [[ $line == ': '*';'* ]] && line=${line#*;}   # tolerate extended history format\n      [[ -n $line ]] && past+=(\"$line\")\n    done\n    recent=(\"${past[@]}\" \"${recent[@]}\")\n    (( ${#recent} > limit )) && recent=(\"${recent[-${limit},-1]}\")\n  fi\n\n  (( ${#recent} )) && printf '%s\\n' \"${recent[@]}\"\n  return 0\n}\n\n_ai_shell_adapter_not_found_message() { printf 'zsh: command not found: %s\\n' \"$1\" >&2; }\n\n_ai_shell_adapter_command_exists() { whence -w \"$1\" >/dev/null 2>&1 }\n\n_ai_shell_adapter_supports_comment() { [[ -o interactive_comments ]] }\n\n# zsh pre-fills the next buffer itself (zle-line-init), so nothing to arm here.\n_ai_shell_adapter_pending_ready() { return 0 }\n\n_ai_shell_adapter_notice() { printf '%s\\n' \"$1\" }\n\n_ai_shell_adapter_doctor() {\n  if [[ ${widgets[accept-line]-} == user:_ai_shell_zsh_accept_line ]]; then\n    printf 'accept-line : ai-shell 已接管\\n'\n  else\n    printf 'accept-line : %s（不是 ai-shell，可能被别的插件覆盖）\\n' \"${widgets[accept-line]:-builtin}\"\n  fi\n  printf 'line-init   : %s\\n' \"${widgets[zle-line-init]:-（未注册）}\"\n  printf 'comments    : %s\\n' \"${options[interactive_comments]}\"\n}\n\n# --- hooks -------------------------------------------------------------------\n\n_ai_shell_zsh_preexec() { AI_SHELL_LAST_CMD=$1 }\n\n_ai_shell_zsh_precmd() {\n  local ret=$?\n  # An empty line keeps $? (measured in both shells), so without this guard a\n  # bare Enter after a failure would re-analyse the same command.\n  local marker=${HISTCMD:-0}\n  if [[ $marker == ${AI_SHELL_LAST_HISTCMD:-} ]]; then\n    _ai_shell_on_prompt 0 \"\"\n    return $ret\n  fi\n  typeset -g AI_SHELL_LAST_HISTCMD=$marker\n  _ai_shell_on_prompt \"$ret\" \"$AI_SHELL_LAST_CMD\"\n  return $ret\n}\n\n# Scenario 1 — natural language typed at the prompt.\n#\n# Do NOT print the panel here: ZLE's line accounting is stale while a widget\n# runs, and its redraw after the widget erases the tail of whatever we wrote\n# (measured: ESC[A×3 + ESC[J wiped the command line, the footer and the blank\n# line).  Hand the query to precmd, which runs with ZLE inactive.\n_ai_shell_zsh_accept_line() {\n  if ! _ai_shell_should_intercept_line \"$BUFFER\"; then\n    if [[ -v widgets[_ai_shell_outer_accept] ]]; then\n      zle _ai_shell_outer_accept\n    else\n      zle .accept-line\n    fi\n    return 0\n  fi\n  typeset -g AI_SHELL_QUERY=$BUFFER\n  BUFFER=\"\" CURSOR=0\n  zle .accept-line\n}\n\n# Delivery: zle-line-init runs inside a widget, so BUFFER can be set here (unlike\n# from the command-not-found subshell).  At line-init the buffer is empty, so\n# nothing the user typed can be clobbered.\n_ai_shell_zsh_line_init() {\n  [[ -s $AI_SHELL_PENDING ]] || return 0\n  local suggestion\n  suggestion=$(cat \"$AI_SHELL_PENDING\")\n  [[ -n $suggestion ]] || return 0\n  rm -f -- \"$AI_SHELL_PENDING\"\n  BUFFER=$suggestion CURSOR=${#suggestion}\n}\n\n_ai_shell_zsh_exit() {\n  zmodload zsh/system 2>/dev/null\n  [[ ${sysparams[pid]} == $$ ]] || return 0   # subshell: leave the parent's dir alone\n  rm -rf -- \"$AI_SHELL_SESSION_DIR\"\n}\n",
  "plugin/zsh/ai-shell.zsh": "# AI Shell — zsh integration entry point (zsh 5.9+).\n#\n# The policy, context assembly and runtime bridge live in\n# plugin/lib/ai-shell-core.sh; this directory only implements what is\n# zsh-specific (see plugin/zsh/adapter.zsh).\n\nif [[ -n ${AI_SHELL_LOADED-} ]]; then\n  return 0\nfi\ntypeset -g AI_SHELL_LOADED=1\ntypeset -g AI_SHELL_NAME=zsh\ntypeset -g AI_SHELL_EXT=zsh\n\n# <repo>/plugin/zsh/ai-shell.zsh -> <repo>\ntypeset -g AI_SHELL_ROOT=${${(%):-%x}:A:h:h:h}\n\n# $EPOCHREALTIME feeds the latency column of the log.\nzmodload zsh/datetime 2>/dev/null\n\n. \"$AI_SHELL_ROOT/plugin/lib/ai-shell-core.sh\"\n. \"$AI_SHELL_ROOT/plugin/zsh/adapter.zsh\"\n\n_ai_shell_setup\n",
};
